//! Cargo integration for Bilimbi's apps/web Tailwind assets (no build.rs counterpart).
//! Output belongs to Cargo, so parallel UI changes never merge generated bytes.
use std::{env, fs, path::Path, path::PathBuf, process::Command};

fn main() {
    let module = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"));
    let root = module
        .join("../../..")
        .canonicalize()
        .expect("Platform root");
    let assets = module.join("assets");
    watch(&root.join("apps"), &module, &assets);
    println!(
        "cargo:rerun-if-changed={}",
        root.join(".gitignore").display()
    );
    let script = root.join("scripts/build-assets.sh");
    println!("cargo:rerun-if-changed={}", script.display());
    let output = PathBuf::from(env::var_os("OUT_DIR").expect("OUT_DIR")).join("app.css");
    let status = Command::new("bash")
        .arg(script)
        .arg("--output")
        .arg(output)
        .status()
        .expect("run scripts/build-assets.sh (requires Node.js >=22 and npm)");
    assert!(
        status.success(),
        "UI asset build failed; see diagnostics above"
    );
}

// Watch source trees, including additions and mounted containers. Split the
// ancestors of assets so npm's cache and the optional local output are excluded:
// neither is an input, and watching them can trigger redundant rebuilds.
fn watch(path: &Path, module: &Path, assets: &Path) {
    if path == assets.join("node_modules") || path == assets.join("app.css") {
        return;
    }
    if module.starts_with(path) || path == assets {
        for entry in fs::read_dir(path).expect("read UI source tree") {
            watch(&entry.expect("UI source entry").path(), module, assets);
        }
    } else {
        println!("cargo:rerun-if-changed={}", path.display());
    }
}
